// AUDIT ROUND 8 (long-seeds): salted copy of tests/review_checkpoint_raise.rs, generated by
// scratchpad/audit8-long-seeds/mk_salted.py. 2 seed site(s) XORed with
// AUDIT8_SALT (0 = the committed seeds). Do not edit; not part of the suite.
//! A checkpoint state raised within the durable proof's horizon.
//!
//! A checkpoint writes and syncs every record it covers into the slots (a v3
//! discard into the discard map) before it publishes its sequence (SPEC §26),
//! and recovery's replay does the same before it advances the state. A
//! CRC-valid checkpoint state raised above the true one, but not above the
//! proof's horizon, used to be accepted: recovery treated the acknowledged
//! records between the two as applied, their units read zeros or an older
//! version, the next checkpoint pruned their journal, and the deep check
//! reported the volume clean. While the covered records survive in the
//! journal, a covered record newer than what its unit's slot (or a v3 discard
//! map) holds proves the state is not one any writer published; recovery and
//! the deep check verify covered records against slot metadata and refuse it
//! before any recovery write. These tests pin that rule for raises the proof
//! still allows, which the checkpoint-horizon refusal does not cover.
//!
//! The negative controls hold the rule to every state a writer does produce:
//! crashes at each step of a checkpoint (before and after it publishes),
//! restart and power loss with torn writes, trims, zeroes and overwrites on
//! v2 and v3, slot damage that replay repairs, and a discard whose journal
//! segment was pruned while an older segment survived.

// Tests that run an engine hold the process-global failpoint lock for their
// whole body, across awaits.
#![allow(clippy::await_holding_lock)]

use std::io;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{Arc, Mutex};

use rand::rngs::StdRng;
use rand::SeedableRng;
use uuid::Uuid;

use maki_backing::Backing;
use maki_core::check::deep_check;
use maki_core::engine::{CheckpointPolicy, Engine, EngineOptions};
use maki_core::recovery::RecoveryError;
use maki_core::volume::{Volume, VolumeOptions};
use maki_format::ab::AbStore;
use maki_format::canary::{KeyCanary, CANARY_UNIT_INDEX};
use maki_format::checker::CheckReport;
use maki_format::checkpoint::{CheckpointState, CHECKPOINT_STATE_A, CHECKPOINT_STATE_B};
use maki_format::durable_proof::DurableProofStore;
use maki_format::geometry::Geometry;
use maki_format::superblock::Superblock;
use maki_format::{init, layout};
use maki_test_support::crash_backing::FaultOp;
use maki_test_support::fake_provider::FakeCryptoProvider;
use maki_test_support::{failpoints, CrashableBacking};

const SEGMENT: u64 = 4096;
const UUID: u128 = 0x5eb1_c0ae;
const UNITS: u64 = 128;
/// Every covered-record refusal names the covered journal record it could
/// not match (a write with no visible slot, a slot at another sequence, a
/// discard missing from the discard map).
const REFUSAL: &str = "covered journal";

fn options() -> VolumeOptions {
    VolumeOptions {
        journal_segment_size: SEGMENT,
    }
}

fn superblock() -> Superblock {
    Superblock {
        generation: 0,
        volume_uuid: Uuid::from_u128(UUID),
        provider_type: "fake".into(),
        crypto_compatibility_id: "test-profile-v1".into(),
        key_identity: "k".into(),
        // 128 units of 512 bytes, 48 per shard; a 572-byte record, so a
        // 4 KiB segment holds seven.
        geometry: Geometry::compute(512, 512, 512, 544, 512 * UNITS, 512 * 48).unwrap(),
        format_version: 1,
        created_unix: 0,
    }
}

fn create_unbound(backing: CrashableBacking, discard: bool) -> Arc<CrashableBacking> {
    let backing = Arc::new(backing);
    if discard {
        init::create_volume_with_discard(backing.as_ref(), superblock()).unwrap();
    } else {
        init::create_volume(backing.as_ref(), superblock()).unwrap();
    }
    backing
}

/// A new volume with a key canary bound, as an engine's first attach binds
/// one, so that the deep check's verdict depends on the journal and slots.
fn create(backing: CrashableBacking, discard: bool) -> Arc<CrashableBacking> {
    let backing = create_unbound(backing, discard);
    let ab = AbStore::new(layout::KEY_CANARY_A, layout::KEY_CANARY_B);
    let mut canary = KeyCanary {
        generation: 0,
        volume_uuid: Uuid::from_u128(UUID),
        unit_index: CANARY_UNIT_INDEX,
        ciphertext: vec![0x5a; 64],
    };
    ab.store(backing.as_ref(), &mut canary).unwrap();
    ab.store(backing.as_ref(), &mut canary).unwrap();
    backing
}

fn recover(backing: &Arc<CrashableBacking>) -> Result<Volume, RecoveryError> {
    Volume::recover(backing.process() as Arc<dyn Backing>, options())
}

fn check(backing: &Arc<CrashableBacking>) -> CheckReport {
    deep_check(backing.clone() as Arc<dyn Backing>, SEGMENT).unwrap()
}

/// Ciphertext unique to (unit, version).
fn ct(unit: u64, version: u64) -> Vec<u8> {
    let mut v = vec![(unit as u8).wrapping_mul(31).wrapping_add(version as u8); 540];
    v[..8].copy_from_slice(&unit.to_le_bytes());
    v[8..16].copy_from_slice(&version.to_le_bytes());
    v
}

fn version_of(volume: &Volume, unit: u64) -> Option<u64> {
    volume
        .read_ct(unit)
        .unwrap()
        .map(|(_, data)| u64::from_le_bytes(data[8..16].try_into().unwrap()))
}

/// Publish a checkpoint state through the ordinary A/B store: a CRC-valid,
/// newer-generation copy, exactly as the writer itself stores one.
fn set_checkpoint_sequence(backing: &CrashableBacking, sequence: u64) {
    let ab = AbStore::new(CHECKPOINT_STATE_A, CHECKPOINT_STATE_B);
    let mut state: CheckpointState = ab.load(backing).unwrap().unwrap();
    state.checkpoint_sequence = sequence;
    ab.store(backing, &mut state).unwrap();
}

fn checkpoint_sequence(backing: &CrashableBacking) -> u64 {
    AbStore::new(CHECKPOINT_STATE_A, CHECKPOINT_STATE_B)
        .load::<CheckpointState>(backing)
        .unwrap()
        .unwrap()
        .checkpoint_sequence
}

fn proof_horizon(backing: &CrashableBacking) -> u64 {
    DurableProofStore::load(backing, Uuid::from_u128(UUID))
        .unwrap()
        .durable_sequence
}

fn observe_mutations(backing: &CrashableBacking) -> Arc<Mutex<Vec<String>>> {
    let mutations = Arc::new(Mutex::new(Vec::new()));
    let observed = mutations.clone();
    backing.set_fault_hook(Some(Arc::new(move |op| {
        if !matches!(op, FaultOp::Open { create: false, .. }) {
            observed.lock().unwrap().push(format!("{op:?}"));
        }
        None
    })));
    mutations
}

/// A volume whose acknowledged history ends above its checkpoint, the
/// checkpoint the writer stored, and the expected version of every unit.
struct Fixture {
    backing: Arc<CrashableBacking>,
    honest: u64,
    expected: Vec<(u64, Option<u64>)>,
}

/// Two FUA writes, never checkpointed (sequences 1 and 2).
fn never_checkpointed(discard: bool) -> Fixture {
    let backing = create(CrashableBacking::new(), discard);
    let mut volume = recover(&backing).unwrap();
    assert_eq!(volume.write_ct(3, &ct(3, 1), true).unwrap(), 1);
    assert_eq!(volume.write_ct(4, &ct(4, 2), true).unwrap(), 2);
    drop(volume);
    Fixture {
        backing,
        honest: 0,
        expected: vec![(3, Some(1)), (4, Some(2))],
    }
}

/// Five writes checkpointed at 5 while their segment is still active, then
/// FUA writes 6 and 7 to new units and 8 overwriting unit 2 (written at 3).
fn after_a_checkpoint(discard: bool) -> Fixture {
    let backing = create(CrashableBacking::new(), discard);
    let mut volume = recover(&backing).unwrap();
    for unit in 0..5u64 {
        volume.write_ct(unit, &ct(unit, unit + 1), false).unwrap();
    }
    volume.flush().unwrap();
    assert_eq!(volume.checkpoint().unwrap(), 5);
    assert_eq!(volume.write_ct(10, &ct(10, 6), true).unwrap(), 6);
    assert_eq!(volume.write_ct(11, &ct(11, 7), true).unwrap(), 7);
    assert_eq!(volume.write_ct(2, &ct(2, 8), true).unwrap(), 8);
    drop(volume);
    Fixture {
        backing,
        honest: 5,
        expected: vec![
            (0, Some(1)),
            (1, Some(2)),
            (2, Some(8)),
            (3, Some(4)),
            (4, Some(5)),
            (10, Some(6)),
            (11, Some(7)),
        ],
    }
}

/// Unit 2 written and checkpointed at 1, then overwritten with FUA at 2.
fn overwritten_after_a_checkpoint(discard: bool) -> Fixture {
    let backing = create(CrashableBacking::new(), discard);
    let mut volume = recover(&backing).unwrap();
    assert_eq!(volume.write_ct(2, &ct(2, 1), true).unwrap(), 1);
    assert_eq!(volume.checkpoint().unwrap(), 1);
    assert_eq!(volume.write_ct(2, &ct(2, 2), true).unwrap(), 2);
    drop(volume);
    Fixture {
        backing,
        honest: 1,
        expected: vec![(2, Some(2))],
    }
}

/// v3: units 8 and 7 written and checkpointed at 2, then unit 7 trimmed
/// with FUA at 3.
fn trimmed_after_a_checkpoint() -> Fixture {
    let backing = create(CrashableBacking::new(), true);
    let mut volume = recover(&backing).unwrap();
    assert_eq!(volume.write_ct(8, &ct(8, 1), true).unwrap(), 1);
    assert_eq!(volume.write_ct(7, &ct(7, 2), true).unwrap(), 2);
    assert_eq!(volume.checkpoint().unwrap(), 2);
    assert_eq!(volume.discard_ct(7, true).unwrap(), 3);
    drop(volume);
    Fixture {
        backing,
        honest: 2,
        expected: vec![(7, None), (8, Some(1))],
    }
}

fn refusal_cases() -> Vec<(String, Fixture, u64)> {
    let mut cases = Vec::new();
    for discard in [false, true] {
        let v = if discard { 3 } else { 2 };
        for raised in [1, 2] {
            cases.push((
                format!("v{v} never checkpointed, raised 0 -> {raised}"),
                never_checkpointed(discard),
                raised,
            ));
        }
        for raised in [6, 8] {
            cases.push((
                format!("v{v} checkpointed at 5, raised 5 -> {raised}"),
                after_a_checkpoint(discard),
                raised,
            ));
        }
        // The slot serves the version the covered write replaced.
        cases.push((
            format!("v{v} overwrite after a checkpoint, raised 1 -> 2"),
            overwritten_after_a_checkpoint(discard),
            2,
        ));
    }
    // Unit 7's slot still serves the version the trim replaced.
    cases.push((
        "v3 trim after a checkpoint, raised 2 -> 3".into(),
        trimmed_after_a_checkpoint(),
        3,
    ));
    cases
}

#[test]
fn raised_checkpoint_within_the_proof_is_refused_by_recovery_and_the_deep_check() {
    for (what, fixture, raised) in refusal_cases() {
        let backing = &fixture.backing;
        assert_eq!(checkpoint_sequence(backing), fixture.honest, "{what}");
        assert!(
            raised <= proof_horizon(backing),
            "{what}: the raise stays within the proof's horizon"
        );
        set_checkpoint_sequence(backing, raised);

        let mutations = observe_mutations(backing);
        let report = check(backing);
        let recovered = recover(backing);
        backing.set_fault_hook(None);

        assert!(
            report.errors.iter().any(|e| e.contains(REFUSAL)),
            "{what}: the deep check passed a raised checkpoint: errors {:?}, info {:?}",
            report.errors,
            report.info
        );
        assert!(
            report
                .info
                .contains(&"deep check verdict: unrecoverable".to_string()),
            "{what}: {:?}",
            report.info
        );
        match recovered {
            Err(RecoveryError::Corrupt(error)) => {
                assert!(error.contains(REFUSAL), "{what}: {error}")
            }
            Err(error) => panic!("{what}: expected corruption, got {error}"),
            Ok(volume) => {
                let reads: Vec<_> = fixture
                    .expected
                    .iter()
                    .map(|(unit, _)| (*unit, version_of(&volume, *unit)))
                    .collect();
                panic!(
                    "{what}: recovery accepted it; reads {reads:?}, expected {:?}",
                    fixture.expected
                )
            }
        }
        let mutations = mutations.lock().unwrap();
        assert!(
            mutations.is_empty(),
            "{what}: storage changed before the refusal: {mutations:?}"
        );
    }
}

/// The refusal leaves the evidence intact: restoring the honest checkpoint
/// state recovers every acknowledged write.
#[test]
fn refused_raise_leaves_the_acknowledged_journal_intact() {
    for (what, fixture, raised) in refusal_cases() {
        let backing = &fixture.backing;
        set_checkpoint_sequence(backing, raised);
        assert!(recover(backing).is_err(), "{what}");
        set_checkpoint_sequence(backing, fixture.honest);
        let report = check(backing);
        assert!(report.ok(), "{what}: {:?}", report.errors);
        let volume = recover(backing).unwrap();
        for (unit, version) in &fixture.expected {
            assert_eq!(version_of(&volume, *unit), *version, "{what}: unit {unit}");
        }
    }
}

// ------------------------------------------------------------ negative controls

/// The deep check reports no error and recovery attaches, serving `expected`.
fn assert_accepted(backing: &Arc<CrashableBacking>, what: &str, expected: &[(u64, Option<u64>)]) {
    let report = check(backing);
    assert!(
        report.ok(),
        "{what}: the deep check refused a writer's state: {:?}",
        report.errors
    );
    let volume = recover(backing).unwrap_or_else(|e| panic!("{what}: recovery refused: {e}"));
    for (unit, version) in expected {
        assert_eq!(version_of(&volume, *unit), *version, "{what}: unit {unit}");
    }
    drop(volume);
    // What recovery publishes is accepted again.
    let report = check(backing);
    assert!(report.ok(), "{what}: after recovery: {:?}", report.errors);
}

/// What the workload acknowledged, per unit (`None`: never written or
/// trimmed).
struct History {
    version: u64,
    expected: Vec<Option<u64>>,
}

impl History {
    fn new() -> Self {
        Self {
            version: 0,
            expected: vec![None; UNITS as usize],
        }
    }

    fn write(&mut self, volume: &mut Volume, unit: u64, fua: bool) {
        self.version += 1;
        let sequence = volume.write_ct(unit, &ct(unit, self.version), fua).unwrap();
        assert_eq!(sequence, self.version);
        self.expected[unit as usize] = Some(self.version);
    }

    fn trim(&mut self, volume: &mut Volume, unit: u64, fua: bool) {
        self.version += 1;
        assert_eq!(volume.discard_ct(unit, fua).unwrap(), self.version);
        self.expected[unit as usize] = None;
    }

    fn units(&self) -> Vec<(u64, Option<u64>)> {
        (0..UNITS)
            .map(|unit| (unit, self.expected[unit as usize]))
            .collect()
    }
}

/// Every surviving covered record is reflected by its slot in each honest
/// state: an active segment the checkpoint covers entirely, a segment that
/// straddles the checkpoint, overwrites, a v2 zero-length record, and v3
/// trims whose slots were punched.
#[test]
fn honest_states_with_covered_records_are_accepted() {
    for discard in [false, true] {
        let v = if discard { 3 } else { 2 };
        let backing = create(CrashableBacking::new(), discard);
        let mut volume = recover(&backing).unwrap();
        let mut history = History::new();
        for unit in [0, 1, 2, 1, 50, 100, 2, 3] {
            history.write(&mut volume, unit, false);
        }
        volume.flush().unwrap();
        volume.checkpoint().unwrap();
        for unit in [1, 4, 50, 2] {
            history.write(&mut volume, unit, true);
        }
        if discard {
            history.trim(&mut volume, 50, true);
            history.trim(&mut volume, 0, false);
        } else {
            // v2 has no discard; a zero-length record is an ordinary write,
            // and its slot holds the empty ciphertext.
            history.version += 1;
            assert_eq!(volume.write_ct(60, &[], true).unwrap(), history.version);
        }
        volume.flush().unwrap();
        // The straddling segment survives the second checkpoint.
        volume.checkpoint().unwrap();
        history.write(&mut volume, 5, true);
        drop(volume);
        let expected: Vec<_> = history
            .units()
            .into_iter()
            .filter(|(unit, _)| *unit != 60)
            .collect();
        assert!(
            checkpoint_sequence(&backing) < proof_horizon(&backing),
            "v{v}: records above the checkpoint"
        );
        assert_accepted(&backing, &format!("v{v} straddling"), &expected);

        // A clean detach: the active segment is entirely covered.
        let mut volume = recover(&backing).unwrap();
        history.write(&mut volume, 6, false);
        volume.flush().unwrap();
        volume.checkpoint().unwrap();
        drop(volume);
        assert_eq!(checkpoint_sequence(&backing), proof_horizon(&backing));
        let expected: Vec<_> = history
            .units()
            .into_iter()
            .filter(|(unit, _)| *unit != 60)
            .collect();
        assert_accepted(&backing, &format!("v{v} covered active segment"), &expected);
    }
}

/// Kill the process at every mutating operation of a checkpoint in turn
/// (every later operation fails, syncs included), then restart (page cache
/// intact) or lose power with torn writes. Slots the checkpoint wrote are
/// newer than the stored state until it publishes; once it has, they hold
/// every covered record.
#[test]
fn crash_at_every_checkpoint_step_is_accepted() {
    let _serial = failpoints::test_lock();
    for discard in [false, true] {
        for power_loss in [false, true] {
            let v = if discard { 3 } else { 2 };
            let mut k = 1;
            loop {
                let backing = create(CrashableBacking::new().with_tearing(128), discard);
                let mut volume = recover(&backing).unwrap();
                let mut history = History::new();
                for unit in [0, 1, 2, 60, 1, 2] {
                    history.write(&mut volume, unit, false);
                }
                volume.flush().unwrap();
                volume.checkpoint().unwrap();
                for unit in [2, 3, 61, 0] {
                    history.write(&mut volume, unit, true);
                }
                if discard {
                    history.trim(&mut volume, 1, true);
                }

                let operations = Arc::new(AtomicU64::new(0));
                let counted = operations.clone();
                backing.set_fault_hook(Some(Arc::new(move |op| {
                    if matches!(op, FaultOp::Open { create: false, .. }) {
                        return None;
                    }
                    (counted.fetch_add(1, Ordering::SeqCst) + 1 >= k)
                        .then(|| io::Error::other("process killed"))
                })));
                let finished = volume.checkpoint().is_ok();
                backing.set_fault_hook(None);
                drop(volume);
                let what = format!(
                    "v{v} killed at checkpoint operation {k}, then {}",
                    if power_loss { "power loss" } else { "restart" }
                );
                if power_loss {
                    backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ k));
                }
                assert_accepted(&backing, &what, &history.units());
                if finished {
                    assert!(k > 1, "{what}: the checkpoint performed no operation");
                    break;
                }
                k += 1;
            }
        }
    }
}

/// Replay rewrites a damaged slot whose unit has a newer record (R4-004):
/// the damage is a warning, never a raised checkpoint, whatever older record
/// of the unit the checkpoint covers.
#[test]
fn slot_damage_repaired_by_replay_is_not_a_raised_checkpoint() {
    for discard in [false, true] {
        for header in [false, true] {
            let backing = create(CrashableBacking::new(), discard);
            let mut volume = recover(&backing).unwrap();
            volume.write_ct(9, &ct(9, 1), true).unwrap();
            volume.write_ct(10, &ct(10, 2), true).unwrap();
            volume.checkpoint().unwrap();
            volume.write_ct(9, &ct(9, 3), true).unwrap();
            drop(volume);
            let geometry = superblock().geometry;
            let (shard, in_shard) = geometry.shard_of_unit(9);
            let file = backing.open(&layout::shard_data(shard), false).unwrap();
            let offset = geometry.slot_offset(in_shard) + if header { 9 } else { 64 + 7 };
            let mut byte = [0u8; 1];
            file.read_at(offset, &mut byte).unwrap();
            file.write_at(offset, &[byte[0] ^ 0x5a]).unwrap();
            file.sync_data().unwrap();

            let what = format!(
                "v{} damaged slot {}",
                if discard { 3 } else { 2 },
                if header { "header" } else { "payload" }
            );
            let report = check(&backing);
            assert!(report.ok(), "{what}: {:?}", report.errors);
            assert!(
                report
                    .info
                    .contains(&"deep check verdict: recoverable".to_string()),
                "{what}: {:?}",
                report.info
            );
            let volume = recover(&backing).unwrap();
            assert_eq!(version_of(&volume, 9), Some(3), "{what}");
            assert_eq!(version_of(&volume, 10), Some(2), "{what}");
        }
    }
}

/// A checkpoint deletes covered segments in order and syncs the directory
/// once; a crash can keep any subset of the unlinks. Here the older segment
/// (unit 9's write) survives while the newer one (its trim) is gone: the
/// covered write is newer than the slot, which the trim emptied, and the
/// discard map explains it.
#[test]
fn a_trim_in_a_pruned_segment_explains_an_older_covered_write() {
    let backing = create(CrashableBacking::new(), true);
    let mut volume = recover(&backing).unwrap();
    let mut version = 0;
    let mut fill = |volume: &mut Volume, segment: u64| {
        while volume.journal_segment_count() as u64 <= segment {
            version += 1;
            volume.write_ct(20, &ct(20, version), false).unwrap();
        }
    };
    volume.write_ct(9, &ct(9, 0), false).unwrap();
    fill(&mut volume, 1);
    volume.discard_ct(9, false).unwrap();
    fill(&mut volume, 2);
    volume.flush().unwrap();
    let mut segments: Vec<String> = backing
        .list(layout::JOURNAL_DIR)
        .unwrap()
        .into_iter()
        .filter(|name| layout::parse_journal_segment(name).is_some())
        .map(|name| format!("{}/{name}", layout::JOURNAL_DIR))
        .collect();
    segments.sort();
    assert_eq!(segments.len(), 3);
    let (first, second) = (segments[0].clone(), segments[1].clone());
    let file = backing.open(&first, false).unwrap();
    let mut saved = vec![0u8; file.len().unwrap() as usize];
    file.read_at(0, &mut saved).unwrap();
    drop(file);
    volume.checkpoint().unwrap();
    assert!(!backing.exists(&first).unwrap());
    assert!(!backing.exists(&second).unwrap());
    drop(volume);
    // The crash undid the first unlink only.
    let file = backing.open(&first, true).unwrap();
    file.write_at(0, &saved).unwrap();
    file.sync_data().unwrap();
    backing.sync_dir(layout::JOURNAL_DIR).unwrap();

    assert_accepted(&backing, "pruned trim", &[(9, None), (20, Some(version))]);
}

/// The engine path: writes, WRITE_ZEROES and TRIM (v3), restarted with
/// covered records in its journal, then the same after a power loss.
#[tokio::test]
async fn engine_writes_zeroes_and_trims_are_accepted() {
    let _serial = failpoints::test_lock();
    for discard in [false, true] {
        // The engine binds its own key canary.
        let backing = create_unbound(CrashableBacking::new().with_tearing(128), discard);
        let options = || EngineOptions {
            checkpoint: CheckpointPolicy {
                emergency_reserve_bytes: 0,
                ..Default::default()
            },
            volume: options(),
            ..EngineOptions::default()
        };
        let attach = || async {
            Engine::attach(
                backing.process() as Arc<dyn Backing>,
                Arc::new(FakeCryptoProvider::new(512)),
                options(),
            )
            .await
            .unwrap()
        };
        let block = |stamp: u8| vec![stamp; 512];
        let engine = attach().await;
        for unit in 0..6u64 {
            engine
                .write(unit * 512, &block(unit as u8 + 1), false)
                .await
                .unwrap();
        }
        engine.flush().await.unwrap();
        engine.checkpoint().await.unwrap();
        engine.write_zeroes(512, 1024, true).await.unwrap();
        engine.write(4 * 512, &block(0x44), true).await.unwrap();
        if discard {
            engine.trim(0, 512, true).await.unwrap();
        }
        engine.checkpoint().await.unwrap();
        engine.write(5 * 512, &block(0x55), true).await.unwrap();
        let expected = [if discard { 0 } else { 1 }, 0, 0, 4, 0x44, 0x55];
        engine.stop_checkpoint_worker().await;
        drop(engine);

        for power_loss in [false, true] {
            if power_loss {
                backing.crash(&mut StdRng::seed_from_u64(crate::a8_salt() ^ 7));
            }
            let report = check(&backing);
            assert!(report.ok(), "power loss {power_loss}: {:?}", report.errors);
            let engine = attach().await;
            for (unit, stamp) in expected.iter().enumerate() {
                assert_eq!(
                    engine.read(unit as u64 * 512, 512).await.unwrap(),
                    block(*stamp),
                    "unit {unit}"
                );
            }
            engine.stop_checkpoint_worker().await;
            drop(engine);
        }
    }
}
